```cpp
#include <iostream>
#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    std::regex urlRegex(R"(\[)\((.*)\])\((.*))");
    std::string html;
    while (std::regex_search(markdown, match, urlRegex)) {
        std::string url = match[1].str();
        // Get the text between the URL and the link
        std::string text = match[2].str();
        // Create the HTML link
        html += "<a href=\"" + url + "\">" + text + "</a>\n\n";
    }
    return html;
}
```

